/* ===== v6.6 HOME FUNCTIONAL LIQUID GLASS ===== */
const V66_HOME_VERSION="v6.6";
const V66_MODAL_STATE={resolve:null,opener:null,keyHandler:null,lastValue:null};
let v66HomePrefsCloudUser="";
let v66HomePrefsSaveTimer=null;

function v66SameId(a,b){return String(a??"")===String(b??"")}
function v66Slug(value){return String(value||"board").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,48)||"board"}
function v66StatusLabel(value){const key=v412StatusKey(value);return({pendiente:"Pendiente",asignada:"Asignada",en_proceso:"En ejecución",en_ejecucion:"En ejecución",en_revision:"En revisión",observado:"Observada",corregido:"Corregida",aprobado:"Aprobada",publicado:"Publicada",completado:"Completada",finalizado:"Finalizada",archivada:"Archivada",planificacion:"Planificación",activa:"Activa",pausada:"Pausada"})[key]||String(value||"Sin estado").replaceAll("_"," ").replace(/^./,c=>c.toUpperCase())}
function v66ApprovalLabel(value){const key=v412StatusKey(value);return({sin_aprobacion:"Sin enviar a aprobación",pendiente:"Pendiente de aprobación",pendiente_alejandro:"Pendiente de Alejandro",validado_alejandro:"Validada por Alejandro",validado_jhulio:"Validada por JHULIO",aprobado:"Aprobada",observado:"Observada",rechazado:"Rechazada"})[key]||v66StatusLabel(value||"sin_aprobacion")}
function v66PriorityLabel(value){const key=String(value||"media").toLowerCase();return({alta:"Alta",urgente:"Urgente",media:"Media",baja:"Baja"})[key]||v66StatusLabel(key)}
function v66FormatDate(value,time=""){if(!value)return"Sin fecha";try{const raw=String(value).includes("T")?String(value):`${value}T${time||"12:00"}`;const date=new Date(raw);if(Number.isNaN(date.getTime()))return`${value}${time?` · ${time}`:""}`;return date.toLocaleString("es-PE",{day:"2-digit",month:"long",year:"numeric",...(time?{hour:"numeric",minute:"2-digit"}:{})})}catch(e){return`${value}${time?` · ${time}`:""}`}}
function v66ParseChecklist(value){if(Array.isArray(value))return value;if(!value)return[];if(typeof value==="object")return Object.values(value);const text=String(value).trim();if(!text)return[];try{const parsed=JSON.parse(text);if(Array.isArray(parsed))return parsed}catch(e){}return text.split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean)}
function v66IsValidUrl(value){if(!value)return false;try{const u=new URL(value);return ["http:","https:"].includes(u.protocol)}catch(e){return false}}
function v66SectionLabel(id){return({home:"Inicio",myday:"Mi día",search:"Buscador",notifications:"Notificaciones",schedulePro:"Horario Pro",workIntel:"Trabajo 360",tasks:"Tareas",approvals:"Aprobaciones",workload:"Carga del equipo",campaigns:"Campañas",editorial:"Editorial",calendarOps:"Calendario operativo",creativeRoomsClean:"Creative Arena",hub:"Creative Hub",assets:"Archivos",wall:"Muro",messages:"Mensajes",profile:"Mi espacio",templates:"Plantillas",incidents:"Incidencias",team:"Equipo",live:"En vivo",control:"Control gerencial",performance:"Rendimiento",reports:"Reportes",automations:"Automatizaciones",governance:"Seguridad y gobernanza",auditpro:"Auditoría",permissions:"Permisos",admin:"Administración",memberProfile:"Perfil del miembro",socialTrash:"Mi basurero",settings:"Conexión"})[id]||"Inicio"}
function v66ExplicitAllowed(module,actions=[]){const rules=Array.isArray(state?.role_permissions)?state.role_permissions:[];const rule=rules.find(p=>String(p.role_code)===String(member?.role_code)&&String(p.module)===String(module)&&actions.includes(String(p.action)));return rule?!!rule.allowed:null}
function v66CanManageTask(t){const explicit=v66ExplicitAllowed("tasks",["edit","update","manage"]);if(explicit!==null)return explicit;return v66SameId(t?.assigned_to,member?.id)||v66SameId(t?.created_by,member?.id)||(typeof isSupervisor==="function"&&isSupervisor())}
function v66CanReviewTask(t){const explicit=v66ExplicitAllowed("approvals",["review","approve","manage"]);if(explicit!==null)return explicit;return (typeof isSupervisor==="function"&&isSupervisor())&&!v66SameId(t?.assigned_to,member?.id)}
function v66SetBusy(button,busy,label="Procesando…"){if(!button)return;button.disabled=!!busy;if(busy){button.dataset.v66Label=button.textContent;button.textContent=label;button.classList.add("v66-busy")}else{button.textContent=button.dataset.v66Label||button.textContent;button.classList.remove("v66-busy")}}
function v66Options(items,selected="",placeholder="Selecciona"){return `<option value="">${esc(placeholder)}</option>${(items||[]).map(item=>`<option value="${esc(item.value)}" ${v66SameId(item.value,selected)?"selected":""}>${esc(item.label)}</option>`).join("")}`}
function v66InputValue(id){return document.getElementById(id)?.value?.trim?.()||""}
function v66InputChecked(id){return !!document.getElementById(id)?.checked}
function v66ModalFocusable(){const modal=document.querySelector("#premiumModalBackdrop.open .premium-modal");if(!modal)return[];return Array.from(modal.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')).filter(el=>el.offsetParent!==null)}

closePremiumModal=function(value=null){
  const backdrop=$("premiumModalBackdrop");
  if(!backdrop?.classList.contains("open"))return;
  backdrop.classList.remove("open");
  backdrop.setAttribute("aria-hidden","true");
  document.body.classList.remove("v66-modal-open");
  if(V66_MODAL_STATE.keyHandler)document.removeEventListener("keydown",V66_MODAL_STATE.keyHandler,true);
  const resolve=V66_MODAL_STATE.resolve,opener=V66_MODAL_STATE.opener;
  V66_MODAL_STATE.resolve=null;V66_MODAL_STATE.opener=null;V66_MODAL_STATE.keyHandler=null;V66_MODAL_STATE.lastValue=value;
  if(typeof resolve==="function")resolve(value);
  requestAnimationFrame(()=>{try{opener?.focus?.()}catch(e){}});
};

openPremiumModal=function({title="Acción",subtitle="",icon="",body="",actions=[]}={}){
  if($("premiumModalBackdrop")?.classList.contains("open"))closePremiumModal(null);
  return new Promise(resolve=>{
    const backdrop=$("premiumModalBackdrop"),bodyEl=$("premiumModalBody"),actionsEl=$("premiumModalActions"),modal=backdrop?.querySelector(".premium-modal");
    if(!backdrop||!bodyEl||!actionsEl||!modal){resolve(null);return}
    V66_MODAL_STATE.resolve=resolve;V66_MODAL_STATE.opener=document.activeElement;
    $("premiumModalIcon").textContent=icon||"";
    $("premiumModalTitle").textContent=title;
    $("premiumModalSub").textContent=subtitle||"";
    bodyEl.innerHTML=body||"";
    actionsEl.innerHTML="";
    $("premiumModalClose").setAttribute("aria-label","Cerrar ventana");
    modal.setAttribute("aria-labelledby","premiumModalTitle");
    modal.setAttribute("aria-describedby","premiumModalSub");
    actions.forEach(a=>{
      const btn=document.createElement("button");btn.type="button";btn.className=a.className||"ghost";btn.textContent=a.label||"Aceptar";
      btn.addEventListener("click",async()=>{
        if(typeof a.onClick==="function"){
          try{v66SetBusy(btn,true,a.loadingLabel||"Procesando…");const result=await a.onClick(btn);if(result===false){v66SetBusy(btn,false);return}closePremiumModal(result===undefined?a.value:result)}catch(err){v66SetBusy(btn,false);premiumToast("No se pudo completar",err?.message||String(err),"error")}
        }else closePremiumModal(a.value);
      });
      actionsEl.appendChild(btn);
    });
    backdrop.classList.add("open");backdrop.setAttribute("aria-hidden","false");document.body.classList.add("v66-modal-open");
    $("premiumModalClose").onclick=()=>closePremiumModal(null);
    backdrop.onclick=e=>{if(e.target===backdrop)closePremiumModal(null)};
    V66_MODAL_STATE.keyHandler=e=>{
      if(!backdrop.classList.contains("open"))return;
      if(e.key==="Escape"){e.preventDefault();closePremiumModal(null);return}
      if(e.key==="Tab"){const f=v66ModalFocusable();if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
    };
    document.addEventListener("keydown",V66_MODAL_STATE.keyHandler,true);
    requestAnimationFrame(()=>{const first=bodyEl.querySelector("input:not([type=file]),select,textarea,button")||$("premiumModalClose");first?.focus?.()});
  });
};

function v66TaskDeliverablesMarkup(t){const assets=(state.assets||[]).filter(a=>v66SameId(a.related_task_id,t.id));const evidence=t.evidence_url;return `<section class="v66-detail-section"><div class="v66-detail-section-head"><div><span>ENTREGABLES</span><h4>Evidencia y archivos</h4></div><b>${assets.length+(evidence?1:0)}</b></div>${evidence?`<a class="v66-evidence-card" href="${esc(evidence)}" target="_blank" rel="noopener"><div><small>ENLACE PRINCIPAL</small><strong>${esc(evidence.replace(/^https?:\/\//,""))}</strong></div><span>Abrir ↗</span></a>`:""}${assets.map(a=>{const url=v415AssetUrl(a);return `<div class="v66-file-row"><div><strong>${esc(a.name||"Archivo")}</strong><span>${esc(a.file_type||"Archivo")} · ${v415FormatBytes(a.file_size)}</span></div>${url?`<a href="${esc(url)}" target="_blank" rel="noopener">Abrir</a>`:""}</div>`}).join("")||(!evidence?`<div class="v66-empty-inline">Todavía no se registraron entregables.</div>`:"")}</section>`}

v412OpenTask=function(id){
  const t=by(state.tasks,id);if(!t?.id)return;
  const checklist=v66ParseChecklist(t.checklist),history=(state.approval_history||[]).filter(h=>v66SameId(h.task_id,t.id)).sort((a,b)=>String(b.created_at||"").localeCompare(String(a.created_at||""))).slice(0,10);
  const status=v412StatusKey(t.status),done=v412TaskDone(t),observed=status==="observado"||v412StatusKey(t.approval_status)==="observado",canManage=v66CanManageTask(t),canReview=v66CanReviewTask(t),late=v412TaskOverdue(t);
  const steps=[
    {label:"Asignada",active:true,meta:"Responsable definido"},
    {label:"En ejecución",active:!["pendiente","asignada"].includes(status),meta:"Trabajo en progreso"},
    {label:"Revisión",active:["en_revision","observado","corregido","aprobado","publicado"].includes(status),meta:"Validación del entregable"},
    {label:"Aprobada",active:done,meta:"Cierre de la tarea"}
  ];
  const body=`<div class="v66-task-detail">
    <div class="v66-workflow">${steps.map((s,i)=>`<div class="v66-workflow-step ${s.active?"done":""} ${!s.active&&steps.slice(0,i).every(x=>x.active)?"current":""}"><i>${i+1}</i><div><strong>${s.label}</strong><span>${s.meta}</span></div></div>`).join("")}</div>
    ${late?`<div class="v66-alert danger"><strong>Tarea vencida</strong><span>La fecha de entrega ya pasó. Actualiza el estado o registra la evidencia.</span></div>`:""}
    <div class="v66-detail-grid">
      <div><span>Estado operativo</span><strong>${esc(v66StatusLabel(t.status))}</strong></div>
      <div><span>Aprobación</span><strong>${esc(v66ApprovalLabel(t.approval_status))}</strong></div>
      <button type="button" data-v66-member="${esc(t.assigned_to||"")}"><span>Responsable</span><strong>${esc(memberName(t.assigned_to))}</strong></button>
      <div><span>Prioridad</span><strong>${esc(v66PriorityLabel(t.priority))}</strong></div>
      <div><span>Entrega</span><strong>${esc(v66FormatDate(t.due_date,t.due_time))}</strong></div>
      <div><span>Proyecto / campaña</span><strong>${esc(nameOf(state.campaigns,t.campaign_id)||"Sin campaña")}</strong></div>
    </div>
    <section class="v66-detail-section"><div class="v66-detail-section-head"><div><span>DESCRIPCIÓN</span><h4>Contexto de trabajo</h4></div></div><p class="v66-description">${esc(t.description||"Sin descripción registrada.")}</p></section>
    ${checklist.length?`<section class="v66-detail-section"><div class="v66-detail-section-head"><div><span>CHECKLIST</span><h4>Elementos de control</h4></div><b>${checklist.length}</b></div><div class="v66-checklist">${checklist.map((x,i)=>{const item=typeof x==="string"?{text:x}:x||{};return `<div class="${item.done?"done":""}"><i>${item.done?"✓":i+1}</i><span>${esc(item.title||item.text||"Elemento")}</span></div>`}).join("")}</div></section>`:""}
    ${v66TaskDeliverablesMarkup(t)}
    ${history.length?`<section class="v66-detail-section"><div class="v66-detail-section-head"><div><span>HISTORIAL</span><h4>Decisiones y revisiones</h4></div><b>${history.length}</b></div><div class="v66-timeline">${history.map(h=>`<div><i></i><section><strong>${esc(v66StatusLabel(h.decision||h.new_status||"Actualización"))}</strong><span>${esc(h.actor_role||memberName(h.actor_id)||"Equipo")}</span><p>${esc(h.comment||"Sin comentario")}</p><time>${h.created_at?new Date(h.created_at).toLocaleString("es-PE"):""}</time></section></div>`).join("")}</div></section>`:""}
    <div class="v66-action-dock">
      ${canManage&&v412TaskNeedsAction(t)?`<button type="button" data-v66-task-action="progress" data-task-id="${esc(t.id)}">Actualizar progreso</button>`:""}
      ${canManage&&v412TaskNeedsAction(t)?`<button type="button" class="primary" data-v66-task-action="deliver" data-task-id="${esc(t.id)}">Entregar evidencia</button><button type="button" data-v66-task-action="attach" data-task-id="${esc(t.id)}">Adjuntar archivo</button>`:""}
      ${canReview&&["en_revision","corregido"].includes(status)?`<button type="button" class="success" data-v66-task-action="validate" data-task-id="${esc(t.id)}">Validar</button><button type="button" class="danger" data-v66-task-action="observe" data-task-id="${esc(t.id)}">Observar</button>`:""}
      ${canManage&&observed?`<button type="button" class="primary" data-v66-task-action="correct" data-task-id="${esc(t.id)}">Corregir entrega</button>`:""}
    </div>
  </div>`;
  openPremiumModal({title:t.title||"Detalle de tarea",subtitle:`${memberName(t.assigned_to)} · ${nameOf(state.clients,t.client_id)||"Sin cliente"}`,icon:"",body,actions:[{label:"Cerrar",value:true,className:"ghost"}]});
  requestAnimationFrame(()=>{
    const host=$("premiumModalBody");if(!host)return;
    host.querySelector("[data-v66-member]")?.addEventListener("click",e=>{const memberId=e.currentTarget.dataset.v66Member;closePremiumModal();if(memberId)openMemberProfile(memberId)});
    host.querySelectorAll("[data-v66-task-action]").forEach(btn=>btn.addEventListener("click",()=>{const action=btn.dataset.v66TaskAction,taskId=btn.dataset.taskId;closePremiumModal();setTimeout(()=>{if(action==="progress")v66OpenProgressModal(taskId);if(action==="deliver")v66OpenDeliveryModal(taskId);if(action==="attach")v66OpenAttachModal(taskId);if(action==="validate")reviewTask(taskId,"validate");if(action==="observe")reviewTask(taskId,"observe");if(action==="correct")v66OpenProgressModal(taskId,"corregido")},30)}));
  });
};

function v66OpenProgressModal(id,preset=""){
  const t=by(state.tasks,id);if(!t)return;
  const current=preset||v412StatusKey(t.status)||"pendiente";
  const body=`<div class="v66-form-grid"><label>Nuevo estado<select id="v66ProgressStatus"><option value="pendiente" ${current==="pendiente"?"selected":""}>Pendiente</option><option value="en_proceso" ${current==="en_proceso"?"selected":""}>En ejecución</option><option value="corregido" ${current==="corregido"?"selected":""}>Corregida</option><option value="en_revision" ${current==="en_revision"?"selected":""}>En revisión</option></select></label><label>Calidad / avance<input id="v66ProgressQuality" type="number" min="0" max="100" placeholder="0 a 100"></label><label class="full">Enlace de evidencia opcional<input id="v66ProgressEvidence" type="url" value="${esc(t.evidence_url||"")}" placeholder="https://..."></label><label class="full">Comentario<textarea id="v66ProgressComment" placeholder="Qué cambió, qué está listo y cuál es el siguiente paso"></textarea></label></div>`;
  openPremiumModal({title:preset==="corregido"?"Registrar corrección":"Actualizar progreso",subtitle:t.title||"Tarea",body,actions:[{label:"Cancelar",value:null,className:"ghost"},{label:"Guardar actualización",className:"primary",loadingLabel:"Guardando…",onClick:async()=>{const evidence=v66InputValue("v66ProgressEvidence");if(evidence&&!v66IsValidUrl(evidence))throw new Error("El enlace de evidencia debe comenzar con http:// o https://");const quality=v66InputValue("v66ProgressQuality");const {error}=await sb.rpc("ibm_v30_update_task",{p_task_id:id,p_status:v66InputValue("v66ProgressStatus"),p_evidence_url:evidence||t.evidence_url||"",p_quality:quality?Number(quality):null,p_comment:v66InputValue("v66ProgressComment")||"Progreso actualizado"});if(error)throw error;await loadAll();renderHome();renderTasks();premiumToast("Progreso actualizado","La tarea ya muestra el nuevo estado.","success");setTimeout(()=>v412OpenTask(id),40);return true}}]});
}

function v66OpenDeliveryModal(id){
  const t=by(state.tasks,id);if(!t)return;
  const body=`<div class="v66-form-grid"><label class="full">Enlace de evidencia<input id="v66DeliveryUrl" type="url" value="${esc(t.evidence_url||"")}" placeholder="https://drive.google.com/..."></label><label class="full">Archivo opcional<input id="v66DeliveryFile" type="file" accept="image/jpeg,image/png,image/webp,text/plain,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx"></label><label>Nombre del archivo<input id="v66DeliveryName" value="Evidencia · ${esc(t.title||"Tarea")}"></label><label>Tipo<input id="v66DeliveryType" placeholder="Documento, imagen, video..."></label><label class="full">Comentario de entrega<textarea id="v66DeliveryComment" placeholder="Resume qué se realizó y qué debe revisar el supervisor"></textarea></label><label class="v66-check full"><input id="v66DeliveryConfirm" type="checkbox"> Confirmo que el entregable está listo para revisión.</label></div>`;
  openPremiumModal({title:"Entregar evidencia",subtitle:t.title||"Tarea",body,actions:[{label:"Cancelar",value:null,className:"ghost"},{label:"Enviar a revisión",className:"primary",loadingLabel:"Enviando…",onClick:async()=>{const url=v66InputValue("v66DeliveryUrl"),file=$("v66DeliveryFile")?.files?.[0];if(!url&&!file)throw new Error("Agrega un enlace o selecciona un archivo.");if(url&&!v66IsValidUrl(url))throw new Error("El enlace debe comenzar con http:// o https://");if(!v66InputChecked("v66DeliveryConfirm"))throw new Error("Confirma que el entregable está listo.");let fileData="",fileType=v66InputValue("v66DeliveryType");if(file){fileData=await v415UploadOrInline(file,{folder:"assets",maxSide:1800,quality:.82,allowDocuments:true});fileType=fileType||file.type;const assetResult=await sb.rpc("ibm_v31_create_asset_inline",{p_name:v66InputValue("v66DeliveryName")||`Evidencia · ${t.title}`,p_client_id:t.client_id||null,p_campaign_id:t.campaign_id||null,p_related_task_id:id,p_file_type:fileType,p_file_size:file.size,p_notes:v66InputValue("v66DeliveryComment"),p_asset_data_url:fileData});if(assetResult.error)throw assetResult.error}const evidence=url||fileData||t.evidence_url||"";const {error}=await sb.rpc("ibm_v30_update_task",{p_task_id:id,p_status:"en_revision",p_evidence_url:evidence,p_quality:null,p_comment:v66InputValue("v66DeliveryComment")||"Entrega enviada a revisión"});if(error)throw error;await loadAll();renderHome();renderTasks();premiumToast("Entrega enviada","La evidencia quedó registrada y la tarea pasó a revisión.","success");setTimeout(()=>v412OpenTask(id),40);return true}}]});
}

function v66OpenAttachModal(id){
  const t=by(state.tasks,id);if(!t)return;
  const body=`<div class="v66-form-grid"><label class="full">Archivo<input id="v66AttachFile" type="file" required accept="image/jpeg,image/png,image/webp,text/plain,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx"></label><label>Nombre<input id="v66AttachName" value="Evidencia · ${esc(t.title||"Tarea")}"></label><label>Tipo<input id="v66AttachType" placeholder="Documento, imagen, PDF..."></label><label class="full">Notas<textarea id="v66AttachNotes" placeholder="Describe el contenido o la versión"></textarea></label></div>`;
  openPremiumModal({title:"Adjuntar archivo",subtitle:t.title||"Tarea",body,actions:[{label:"Cancelar",value:null,className:"ghost"},{label:"Subir y vincular",className:"primary",loadingLabel:"Subiendo…",onClick:async()=>{const file=$("v66AttachFile")?.files?.[0];if(!file)throw new Error("Selecciona un archivo.");const data=await v415UploadOrInline(file,{folder:"assets",maxSide:1800,quality:.82,allowDocuments:true});const {error}=await sb.rpc("ibm_v31_create_asset_inline",{p_name:v66InputValue("v66AttachName")||file.name,p_client_id:t.client_id||null,p_campaign_id:t.campaign_id||null,p_related_task_id:id,p_file_type:v66InputValue("v66AttachType")||file.type,p_file_size:file.size,p_notes:v66InputValue("v66AttachNotes"),p_asset_data_url:data});if(error)throw error;await loadAll();renderHome();renderAssets();premiumToast("Archivo adjuntado","El archivo quedó vinculado a la tarea.","success");setTimeout(()=>v412OpenTask(id),40);return true}}]});
}

v413DeliverTask=function(id){v66OpenDeliveryModal(id)};
v415PrepareAssetForTask=function(id){v66OpenAttachModal(id)};
v413PrepareTaskUpdate=function(id,status){v66OpenProgressModal(id,status||"")};

v413OpenCampaign=function(id){
  const c=by(state.campaigns,id);if(!c)return;
  const tasks=(state.tasks||[]).filter(t=>v66SameId(t.campaign_id,id)),done=tasks.filter(v412TaskDone),late=tasks.filter(t=>v412TaskOverdue(t)),briefs=(state.briefs||[]).filter(b=>v66SameId(b.campaign_id,id)),editorial=(state.editorial||[]).filter(e=>v66SameId(e.campaign_id,id)),assets=(state.assets||[]).filter(a=>v66SameId(a.campaign_id,id)),progress=tasks.length?Math.round(done.length*100/tasks.length):0;
  const body=`<div class="v66-campaign-detail"><div class="v66-detail-grid six"><div><span>Avance</span><strong>${progress}%</strong></div><div><span>Tareas</span><strong>${tasks.length}</strong></div><div><span>Vencidas</span><strong>${late.length}</strong></div><div><span>Entregables</span><strong>${assets.length}</strong></div><div><span>Briefs</span><strong>${briefs.length}</strong></div><div><span>Publicaciones</span><strong>${editorial.length}</strong></div></div><section class="v66-detail-section"><div class="v66-detail-section-head"><div><span>OBJETIVO</span><h4>${esc(v66StatusLabel(c.status||"planificación"))}</h4></div></div><p class="v66-description">${esc(c.objective||"Sin objetivo registrado")}</p></section><section class="v66-detail-section"><div class="v66-detail-section-head"><div><span>TAREAS VINCULADAS</span><h4>Trabajo de la campaña</h4></div><b>${tasks.length}</b></div><div class="v66-campaign-tasks">${tasks.length?tasks.slice(0,12).map(t=>`<button type="button" data-v66-campaign-task="${esc(t.id)}"><div><strong>${esc(t.title)}</strong><span>${esc(memberName(t.assigned_to))} · ${esc(v66StatusLabel(t.status))}</span></div><time>${esc(v66FormatDate(t.due_date))}</time></button>`).join(""):`<div class="v66-empty-inline">Sin tareas vinculadas.</div>`}</div></section><div class="v66-action-dock"><button type="button" class="primary" data-v66-campaign-action="task">Crear tarea</button><button type="button" data-v66-campaign-action="editorial">Ver editorial</button><button type="button" data-v66-campaign-action="assets">Ver archivos</button></div></div>`;
  openPremiumModal({title:c.name||"Campaña",subtitle:`${nameOf(state.clients,c.client_id)||"Sin cliente"} · ${v66StatusLabel(c.status||"planificación")}`,body,actions:[{label:"Cerrar",value:true,className:"ghost"}]});
  requestAnimationFrame(()=>{const host=$("premiumModalBody");host?.querySelectorAll("[data-v66-campaign-task]").forEach(b=>b.addEventListener("click",()=>{const taskId=b.dataset.v66CampaignTask;closePremiumModal();setTimeout(()=>v412OpenTask(taskId),30)}));host?.querySelector('[data-v66-campaign-action="task"]')?.addEventListener("click",()=>{closePremiumModal();setTimeout(()=>v66QuickTaskModal(id),30)});host?.querySelector('[data-v66-campaign-action="editorial"]')?.addEventListener("click",()=>{closePremiumModal();navTo("editorial")});host?.querySelector('[data-v66-campaign-action="assets"]')?.addEventListener("click",()=>{closePremiumModal();navTo("assets")})});
};

