homePreferenceKey=function(){return `inbestiga:home:v66:${member?.id||"guest"}`};
homeDefaultPreferences=function(){return{theme:"porcelain",density:"comfortable",widgets:{campaigns:true,activity:true,team:true,social:true}}};
homeLoadPreferences=function(){if(ibHomePreferences)return ibHomePreferences;try{const raw=localStorage.getItem(homePreferenceKey());ibHomePreferences={...homeDefaultPreferences(),...(raw?JSON.parse(raw):{})};ibHomePreferences.widgets={...homeDefaultPreferences().widgets,...(ibHomePreferences.widgets||{})}}catch(e){ibHomePreferences=homeDefaultPreferences()}return ibHomePreferences};
function v66PersistHomePreferences(){clearTimeout(v66HomePrefsSaveTimer);v66HomePrefsSaveTimer=setTimeout(async()=>{if(!sb||!authUser?.id)return;try{const table=sb.schema?.("marketing_app")?.from("home_preferences");if(!table)return;const result=await table.upsert({user_id:authUser.id,preferences:homeLoadPreferences(),updated_at:new Date().toISOString()},{onConflict:"user_id"});if(result.error)throw result.error}catch(e){console.warn("Preferencias Home: modo local",e)}},350)}
homeSavePreferences=function(){try{localStorage.setItem(homePreferenceKey(),JSON.stringify(homeLoadPreferences()))}catch(e){}v66PersistHomePreferences()};
async function v66LoadCloudHomePreferences(){if(!sb||!authUser?.id||v66HomePrefsCloudUser===authUser.id)return;v66HomePrefsCloudUser=authUser.id;try{const table=sb.schema?.("marketing_app")?.from("home_preferences");if(!table)return;const result=await table.select("preferences").eq("user_id",authUser.id).maybeSingle();if(result.error)throw result.error;if(result.data?.preferences){ibHomePreferences={...homeDefaultPreferences(),...result.data.preferences,widgets:{...homeDefaultPreferences().widgets,...(result.data.preferences.widgets||{})}};localStorage.setItem(homePreferenceKey(),JSON.stringify(ibHomePreferences));homeApplyPreferences()}}catch(e){console.warn("Preferencias Home cloud no disponibles",e)}}
homeApplyPreferences=function(){const root=$("home");if(!root)return;const p=homeLoadPreferences();root.dataset.homeTheme=p.theme||"porcelain";root.dataset.homeDensity=p.density||"comfortable";document.querySelectorAll("[data-home-theme-choice]").forEach(b=>b.classList.toggle("active",b.dataset.homeThemeChoice===p.theme));document.querySelectorAll("[data-home-density-choice]").forEach(b=>b.classList.toggle("active",b.dataset.homeDensityChoice===p.density));Object.entries(p.widgets||{}).forEach(([key,val])=>{const box=$("homeWidget"+key.charAt(0).toUpperCase()+key.slice(1));if(box)box.checked=val!==false;document.querySelectorAll(`[data-home-widget="${key}"]`).forEach(el=>el.classList.toggle("home-widget-hidden",val===false));document.querySelectorAll(`[data-home-target-widget="${key}"]`).forEach(el=>el.hidden=val===false)});const insight=root.querySelector(".ib-home-insight-grid");if(insight){const visible=Array.from(insight.children).filter(el=>!el.classList.contains("home-widget-hidden"));insight.classList.toggle("v66-single",visible.length===1);insight.classList.toggle("home-widget-hidden",visible.length===0)}};
homeSetTheme=function(theme){homeLoadPreferences().theme=theme;homeSavePreferences();homeApplyPreferences()};
homeSetDensity=function(density){homeLoadPreferences().density=density;homeSavePreferences();homeApplyPreferences()};
homeSetWidget=function(key,value){homeLoadPreferences().widgets[key]=!!value;homeSavePreferences();homeApplyPreferences()};
homeResetPreferences=function(){ibHomePreferences=homeDefaultPreferences();homeSavePreferences();homeApplyPreferences();premiumToast("Inicio restablecido","Se restauró la configuración predeterminada.","success")};
homeToggleCreate=function(force){const menu=$("homeCreateMenu"),button=$("homeCreateButton");if(!menu)return;const open=typeof force==="boolean"?force:!menu.classList.contains("open");if(open)homeToggleCustomize(false);menu.classList.toggle("open",open);menu.setAttribute("aria-hidden",String(!open));button?.setAttribute("aria-expanded",String(open));if(open)requestAnimationFrame(()=>menu.querySelector("button")?.focus())};
homeToggleCustomize=function(force){const panel=$("homeCustomizePanel"),scrim=$("homeCustomizeScrim"),button=$("homeCustomizeButton");if(!panel||!scrim)return;const open=typeof force==="boolean"?force:!panel.classList.contains("open");if(open)homeToggleCreate(false);panel.classList.toggle("open",open);scrim.classList.toggle("open",open);panel.setAttribute("aria-hidden",String(!open));button?.setAttribute("aria-expanded",String(open));document.body.classList.toggle("v66-home-panel-open",open);if(open){homeApplyPreferences();requestAnimationFrame(()=>panel.querySelector("button,input")?.focus())}};
