renderHome=function(){
  document.body.classList.add("ib-home-mode");syncHomeClock();
  const supervisor=typeof isSupervisor==="function"&&isSupervisor(),tasks=(state.tasks||[]).slice(),open=tasks.filter(t=>!v412TaskDone(t)),actionable=open.filter(v412TaskNeedsAction),mine=actionable.filter(t=>v66SameId(t.assigned_to,member.id)),scopeOpen=supervisor?actionable:mine,todayKey=today(),dueToday=scopeOpen.filter(t=>v412TaskDueToday(t,todayKey)),lateScope=scopeOpen.filter(t=>v412TaskOverdue(t,todayKey)),focusTasks=[...lateScope,...dueToday,...scopeOpen.filter(t=>!t.due_date)].filter((t,i,a)=>a.findIndex(x=>v66SameId(x.id,t.id))===i).slice(0,5);
  const reviewStatuses=new Set(["en_revision","corregido"]),observedStatuses=new Set(["observado"]);const approvalQueue=tasks.filter(t=>supervisor?reviewStatuses.has(v412StatusKey(t.status)):v66SameId(t.assigned_to,member.id)&&observedStatuses.has(v412StatusKey(t.status)));
  const campaigns=(state.campaigns||[]).filter(c=>!["finalizada","archivada"].includes(v412StatusKey(c.status))),campaignRisks=campaigns.filter(c=>c.end_date&&c.end_date<todayKey),posts=activePosts().slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));
  const perf=typeof getMemberPerformance==="function"?getMemberPerformance(member.id):{level:1,levelProgress:0,score360:0,xp:0},rank=typeof v411Rank==="function"?v411Rank(perf.level||1):"Iniciado",now=Date.now(),presenceMap=new Map((state.live_presence||[]).map(p=>[String(p.member_id),p]));
  const membersSorted=(state.members||[]).slice().sort((a,b)=>{const pa=presenceMap.get(String(a.id)),pb=presenceMap.get(String(b.id)),oa=pa&&(now-new Date(pa.updated_at||pa.last_seen_at).getTime())<90000,ob=pb&&(now-new Date(pb.updated_at||pb.last_seen_at).getTime())<90000;return Number(ob)-Number(oa)||String(a.full_name||"").localeCompare(String(b.full_name||""))});
  const onlineMembers=membersSorted.filter(m=>{const p=presenceMap.get(String(m.id));return p&&(now-new Date(p.updated_at||p.last_seen_at).getTime())<90000}),unread=(typeof unreadMessages==="function"?unreadMessages():[])||[],notifications=(state.notifications||[]).filter(n=>!n.read_at),first=(member.full_name||"Equipo").split(/\s+/)[0],date=new Date();
  if($("homeDateLabel"))$("homeDateLabel").textContent=date.toLocaleDateString("es-PE",{weekday:"long",day:"2-digit",month:"long"});
  if($("homeHeroTitle"))$("homeHeroTitle").innerHTML=supervisor?`Buenos días, ${esc(first)}.<br><span>Todo bajo control.</span>`:`Buenos días, ${esc(first)}.<br><span>Avanza con claridad.</span>`;
  if($("homeHeroSubtitle"))$("homeHeroSubtitle").textContent=supervisor?"Prioridades reales, riesgos sin duplicar y decisiones que puedes resolver desde el mismo lugar.":"Tareas de hoy, entregas, mensajes y accesos recientes listos para continuar sin perder contexto.";
  const area=(state.areas||[]).find(a=>v66SameId(a.id,member.area_id));if($("homeMemberAvatar"))$("homeMemberAvatar").innerHTML=(member.avatar_data_url||imgSrc(member.avatar_url))?`<img src="${esc(member.avatar_data_url||member.avatar_url)}" alt="Foto de ${esc(member.full_name||"miembro")}">`:esc(initials(member.full_name||"iB"));
  if($("homeMemberArea"))$("homeMemberArea").textContent=(area?.name||member.area_name||"EQUIPO").toUpperCase();if($("homeMemberName"))$("homeMemberName").textContent=member.full_name||"Miembro";if($("homeMemberRole"))$("homeMemberRole").textContent=roleLabel();if($("homeMemberLevel"))$("homeMemberLevel").textContent=perf.level||1;if($("homeMemberRank"))$("homeMemberRank").textContent=rank;if($("homeMemberScore"))$("homeMemberScore").textContent=perf.score360||0;
  const xpPct=Math.max(0,Math.min(100,Number(perf.levelProgress)||0));if($("homeMemberXpFill"))$("homeMemberXpFill").style.width=`${xpPct}%`;if($("homeMemberXpText"))$("homeMemberXpText").textContent=`${Math.round(xpPct)}%`;
  const summary=[];if(mine.length)summary.push(`${mine.length} tarea${mine.length===1?"":"s"} abierta${mine.length===1?"":"s"}`);if(approvalQueue.length)summary.push(`${approvalQueue.length} acción${approvalQueue.length===1?"":"es"} requerida${approvalQueue.length===1?"":"s"}`);if(unread.length)summary.push(`${unread.length} mensaje${unread.length===1?"":"s"} nuevo${unread.length===1?"":"s"}`);if($("homeMemberSummary"))$("homeMemberSummary").textContent=summary.length?`Tienes ${summary.join(", ")}.`:"No tienes pendientes críticos en este momento.";
  if($("homeLiveStatus"))$("homeLiveStatus").innerHTML=`<i></i> ${realtimeAvailable?"Realtime activo":"Sincronización disponible"}`;
  if($("homeMetricToday"))$("homeMetricToday").textContent=dueToday.length;if($("homeMetricApprovals"))$("homeMetricApprovals").textContent=approvalQueue.length;if($("homeMetricRisks"))$("homeMetricRisks").textContent=lateScope.length+campaignRisks.length;if($("homeMetricOnline"))$("homeMetricOnline").textContent=onlineMembers.length;
  if($("homeNotificationBadge")){const count=notifications.length;$("homeNotificationBadge").textContent=count;$("homeNotificationBadge").style.display=count?"block":"none"}if($("homeMessageBadge")){const count=unread.length;$("homeMessageBadge").textContent=count;$("homeMessageBadge").style.display=count?"block":"none"}
  if($("homeTodayList"))$("homeTodayList").innerHTML=focusTasks.map(homeTaskListItem).join("")||`<div class="ib-home-empty"><div><strong>Tu agenda está despejada.</strong><br><span>No hay tareas vencidas ni entregas programadas para hoy.</span></div></div>`;
  const riskItems=[];lateScope.slice(0,3).forEach(t=>riskItems.push(homeRiskItem("task",t.title,`Venció ${homeShortDate(t.due_date)} · ${memberName(t.assigned_to)}`,`homeOpenTask('${esc(t.id)}')`,"danger")));approvalQueue.slice(0,3).forEach(t=>riskItems.push(homeRiskItem("approval",t.title,supervisor?`Esperando revisión · ${memberName(t.assigned_to)}`:"La entrega fue observada y requiere corrección",`homeOpenTask('${esc(t.id)}')`,v412StatusKey(t.status)==="observado"?"danger":"warning")));campaignRisks.slice(0,2).forEach(c=>riskItems.push(homeRiskItem("campaign",c.name,`Finalizó ${homeShortDate(c.end_date)} · ${nameOf(state.clients,c.client_id)||"Sin cliente"}`,`homeOpenCampaign('${esc(c.id)}')`,"danger")));
  if($("homeRiskCount"))$("homeRiskCount").textContent=riskItems.length;if($("homeRiskList"))$("homeRiskList").innerHTML=riskItems.slice(0,6).join("")||`<div class="ib-home-empty"><div><strong>Todo avanza con normalidad.</strong><br><span>No se detectaron vencimientos ni decisiones urgentes.</span></div></div>`;
  const last=homeLastSection(),lastTitle=v66SectionLabel(last),recentTask=(mine.length?mine:scopeOpen).slice().sort((a,b)=>new Date(b.updated_at||b.created_at)-new Date(a.updated_at||a.created_at))[0],recentCampaign=campaigns.slice().sort((a,b)=>new Date(b.updated_at||b.created_at)-new Date(a.updated_at||a.created_at))[0];
  const continueCards=[{icon:"↗",label:"Último módulo",title:lastTitle,meta:"Retoma el último espacio que abriste.",accent:"#0a84ff",action:`navTo('${esc(last)}')`},{icon:"✓",label:"Tarea activa",title:recentTask?.title||"Revisa tu agenda",meta:recentTask?`${memberName(recentTask.assigned_to)} · ${homeShortDate(recentTask.due_date)}`:"Organiza tus prioridades en Mi día.",accent:"#1ca56b",action:recentTask?`homeOpenTask('${esc(recentTask.id)}')`:`navTo('myday')`},{icon:"◉",label:"Campaña",title:recentCampaign?.name||"Campañas activas",meta:recentCampaign?`${nameOf(state.clients,recentCampaign.client_id)||"Sin cliente"} · ${v66StatusLabel(recentCampaign.status)}`:"Consulta proyectos, briefs y entregables.",accent:"#a855f7",action:recentCampaign?`homeOpenCampaign('${esc(recentCampaign.id)}')`:`navTo('campaigns')`},{icon:"✦",label:"Espacio creativo",title:"Creative Arena",meta:"Abre tu última sala creativa o crea una nueva.",accent:"#ff9f0a",action:"navTo('creativeRoomsClean')"}];
  if($("homeContinueGrid"))$("homeContinueGrid").innerHTML=continueCards.map(c=>`<button type="button" class="ib-home-continue-card" style="--card-accent:${c.accent}" onclick="${c.action}"><span class="ib-home-continue-icon">${c.icon}</span><div><small>${esc(c.label)}</small><strong>${esc(c.title)}</strong><span>${esc(c.meta)}</span></div></button>`).join("");if($("homeContinuePrimary"))$("homeContinuePrimary").textContent=`Continuar en ${lastTitle}`;
  const campaignSorted=campaigns.slice().sort((a,b)=>Number(campaignRisks.some(c=>v66SameId(c.id,b.id)))-Number(campaignRisks.some(c=>v66SameId(c.id,a.id)))||new Date(b.updated_at||b.created_at)-new Date(a.updated_at||a.created_at));
  if($("homeCampaignGrid"))$("homeCampaignGrid").innerHTML=campaignSorted.slice(0,6).map(c=>{const ct=tasks.filter(t=>v66SameId(t.campaign_id,c.id)),done=ct.filter(v412TaskDone),clate=ct.filter(t=>v412TaskOverdue(t,todayKey)),progress=ct.length?Math.round(done.length*100/ct.length):0,risk=campaignRisks.some(x=>v66SameId(x.id,c.id))||clate.length>0;return`<button type="button" class="ib-home-campaign-card" onclick="homeOpenCampaign('${esc(c.id)}')"><div class="ib-home-campaign-top"><span class="ib-home-campaign-orb"></span><span class="ib-home-campaign-state ${risk?"risk":""}">${risk?`${clate.length||1} en riesgo`:esc(v66StatusLabel(c.status||"Activa"))}</span></div><div><h3>${esc(c.name||"Campaña")}</h3><p>${esc(c.objective||nameOf(state.clients,c.client_id)||"Proyecto activo del equipo")}</p></div><div class="ib-home-campaign-progress"><div><span>Progreso</span><b>${progress}%</b></div><div class="ib-home-campaign-track"><i style="width:${progress}%"></i></div></div><div class="ib-home-campaign-meta"><span>${ct.length} tareas</span><span>${nameOf(state.clients,c.client_id)||"Sin cliente"}</span></div></button>`}).join("")||`<div class="ib-home-empty" style="grid-column:1/-1"><div><strong>No hay campañas activas.</strong><br><span>Crea una campaña para verla en este centro de mando.</span></div></div>`;
  const activity=[];(state.live_events||[]).forEach(e=>activity.push({icon:"◎",title:e.title||v66StatusLabel(e.event_type||"Actividad"),meta:`${memberName(e.actor_id)} · ${e.body||"Actualización del equipo"}`,date:e.created_at,type:e.entity_type,id:e.entity_id,section:e.current_section||"notifications"}));tasks.slice().sort((a,b)=>new Date(b.updated_at||b.created_at)-new Date(a.updated_at||a.created_at)).slice(0,6).forEach(t=>activity.push({icon:"✓",title:t.title,meta:`${memberName(t.assigned_to)} · ${v66StatusLabel(t.status)}`,date:t.updated_at||t.created_at,type:"task",id:t.id,section:"tasks"}));activity.sort((a,b)=>new Date(b.date)-new Date(a.date));
  if($("homeActivityList"))$("homeActivityList").innerHTML=activity.slice(0,8).map(a=>`<button type="button" class="ib-home-activity-item" onclick="homeOpenActivity('${esc(a.type||"")}','${esc(a.id||"")}','${esc(a.section||"notifications")}')"><span class="ib-home-activity-icon">${a.icon}</span><span class="ib-home-activity-copy"><strong>${esc(a.title||"Actividad")}</strong><span>${esc(a.meta||"")}</span></span><time>${homeRelativeTime(a.date)}</time></button>`).join("")||`<div class="ib-home-empty">Todavía no hay actividad reciente.</div>`;
  if($("homeTeamGrid"))$("homeTeamGrid").innerHTML=membersSorted.slice(0,10).map(m=>{const p=presenceMap.get(String(m.id)),seen=p?new Date(p.updated_at||p.last_seen_at).getTime():0,online=seen&&(now-seen)<90000;return`<button type="button" class="ib-home-person" onclick="openMemberProfile('${esc(m.id)}')">${homeAvatarMarkup(m)}<span class="ib-home-person-copy"><strong>${esc(m.full_name||"Miembro")}</strong><span>${esc(online?v66SectionLabel(p?.current_section||"live"):(m.position||m.role_code||"Desconectado"))}</span></span><i class="ib-home-person-status ${online?"online":""}"></i></button>`}).join("")||`<div class="ib-home-empty" style="grid-column:1/-1">No hay miembros registrados.</div>`;
  if($("homeSocialPreview"))$("homeSocialPreview").innerHTML=posts.slice(0,3).map(p=>{const u=by(state.members,p.author_id)||{},dateLabel=p.created_at?new Date(p.created_at).toLocaleDateString("es-PE",{day:"2-digit",month:"short"}):"",reacts=Object.values(reactionsFor("wall_post",p.id)).reduce((a,b)=>a+b,0),image=imgSrc(p.image_url||p.image_data_url);return`<article class="ib-home-social-card" data-post-id="${esc(p.id)}"><div class="ib-home-social-author">${homeAvatarMarkup(u,"mini-avatar")}<div><strong>${esc(u.full_name||"Miembro")}</strong><span>${esc(dateLabel)}</span></div></div><p>${esc((p.text_content||"Publicación del equipo").slice(0,260))}</p>${image?`<img src="${esc(image)}" alt="Publicación del equipo">`:""}<div class="ib-home-social-foot"><span>${reacts} reacciones</span><button type="button" onclick="homeOpenPost('${esc(p.id)}')">Ver publicación</button></div></article>`}).join("")||`<div class="ib-home-empty" style="grid-column:1/-1">Todavía no hay publicaciones recientes.</div>`;
  homeApplyPreferences();v66LoadCloudHomePreferences();
};

function v66BindHomeGlobal(){
  document.addEventListener("click",e=>{const create=$("homeCreateMenu"),createBtn=$("homeCreateButton"),custom=$("homeCustomizePanel"),customBtn=$("homeCustomizeButton");if(create?.classList.contains("open")&&!create.contains(e.target)&&!createBtn?.contains(e.target))homeToggleCreate(false);if(custom?.classList.contains("open")&&!custom.contains(e.target)&&!customBtn?.contains(e.target)&&!e.target.closest("#homeCustomizeScrim"))homeToggleCustomize(false)});
  document.addEventListener("keydown",e=>{if(e.key!=="Escape")return;if($("homeCreateMenu")?.classList.contains("open"))homeToggleCreate(false);if($("homeCustomizePanel")?.classList.contains("open"))homeToggleCustomize(false)});
}
if(!window.__v66HomeBound){window.__v66HomeBound=true;v66BindHomeGlobal()}
